// App.js
import React, { useState } from "react";
import { sendRequest } from "./requests/requests";
import "./App.css";

function App() {
  const [imageFile, setImageFile] = useState(null);
  const [secondImage, setSecondImage] = useState(null);
  const [operation, setOperation] = useState("gray");
  const [params, setParams] = useState({});
  const [resultUrl, setResultUrl] = useState("");
  const [previewUrl, setPreviewUrl] = useState("");
  const [previewSecond, setPreviewSecond] = useState("");

  const handleSubmit = async () => {
    if (!imageFile) {
      alert("Lütfen bir görsel yükleyin.");
      return;
    }

    const data = await sendRequest({
      operation,
      imageFile,
      secondImageFile: secondImage,
      params,
    });

    if (data?.url) {
      setResultUrl(data.url);
    } else {
      alert("İşlem başarısız oldu.");
      setResultUrl("");
    }
  };

  const handleImageChange = (e) => {
    const file = e.target.files[0];
    setImageFile(file);
    if (file) setPreviewUrl(URL.createObjectURL(file));
  };

  const handleSecondImageChange = (e) => {
    const file = e.target.files[0];
    setSecondImage(file);
    if (file) setPreviewSecond(URL.createObjectURL(file));
  };

  const renderParams = () => {
    switch (operation) {
      case "binary":
        return <input type="number" className="param-input" placeholder="Threshold" defaultValue={127} onChange={(e) => setParams({ threshold: Number(e.target.value) })} />;
      case "rotate":
        return <input type="number" className="param-input" placeholder="Açı" defaultValue={90} onChange={(e) => setParams({ angle: Number(e.target.value) })} />;
      case "zoom":
        return <input type="number" className="param-input" step="0.1" placeholder="Ölçek" defaultValue={1.2} onChange={(e) => setParams({ scale: Number(e.target.value) })} />;
      case "contrast":
        return <input type="number" className="param-input" step="0.1" placeholder="Faktör (0-1)" defaultValue={0.5} onChange={(e) => setParams({ factor: Number(e.target.value) })} />;
      case "motion":
      case "median":
        return <input type="number" className="param-input" placeholder="Çekirdek Boyutu" defaultValue={3} onChange={(e) => setParams({ kernel_size: Number(e.target.value) })} />;
      case "color":
        return (
          <select className="param-input" defaultValue="HSV" onChange={(e) => setParams({ mode: e.target.value })}>
            <option value="HSV">HSV</option>
            <option value="YUV">YUV</option>
            <option value="LAB">LAB</option>
          </select>
        );
      case "double_threshold":
        return (
          <div className="param-group">
            <input type="number" className="param-input" placeholder="Alt Eşik" defaultValue={50} onChange={(e) => setParams((prev) => ({ ...prev, low_thresh: Number(e.target.value) }))} />
            <input type="number" className="param-input" placeholder="Üst Eşik" defaultValue={150} onChange={(e) => setParams((prev) => ({ ...prev, high_thresh: Number(e.target.value) }))} />
          </div>
        );
      case "edge":
        return (
          <div className="param-group">
            <input type="number" className="param-input" placeholder="Threshold 1" defaultValue={100} onChange={(e) => setParams((prev) => ({ ...prev, threshold1: Number(e.target.value) }))} />
            <input type="number" className="param-input" placeholder="Threshold 2" defaultValue={200} onChange={(e) => setParams((prev) => ({ ...prev, threshold2: Number(e.target.value) }))} />
          </div>
        );
      case "crop":
        return (
          <div className="param-group">
            <input type="number" className="param-input" placeholder="X" defaultValue={0} onChange={(e) => setParams((prev) => ({ ...prev, x: Number(e.target.value) }))} />
            <input type="number" className="param-input" placeholder="Y" defaultValue={0} onChange={(e) => setParams((prev) => ({ ...prev, y: Number(e.target.value) }))} />
            <input type="number" className="param-input" placeholder="Genişlik" defaultValue={200} onChange={(e) => setParams((prev) => ({ ...prev, width: Number(e.target.value) }))} />
            <input type="number" className="param-input" placeholder="Yükseklik" defaultValue={200} onChange={(e) => setParams((prev) => ({ ...prev, height: Number(e.target.value) }))} />
          </div>
        );
      case "noise":
        return <input type="number" step="0.01" className="param-input" placeholder="Miktar (0-1)" defaultValue={0.02} onChange={(e) => setParams({ amount: Number(e.target.value) })} />;
      case "denoise":
        return (
          <div className="param-group">
            <select className="param-input" defaultValue="mean" onChange={(e) => setParams((prev) => ({ ...prev, filter_type: e.target.value }))}>
              <option value="mean">Mean</option>
              <option value="median">Median</option>
            </select>
            <input type="number" className="param-input" placeholder="Çekirdek" defaultValue={3} onChange={(e) => setParams((prev) => ({ ...prev, kernel_size: Number(e.target.value) }))} />
          </div>
        );
      case "morphology":
        return (
          <div className="param-group">
            <select className="param-input" defaultValue="dilate" onChange={(e) => setParams((prev) => ({ ...prev, morph_op: e.target.value }))}>
              <option value="dilate">Genişlet</option>
              <option value="erode">Aşındır</option>
              <option value="open">Açma</option>
              <option value="close">Kapama</option>
            </select>
            <input type="number" className="param-input" placeholder="Çekirdek" defaultValue={3} onChange={(e) => setParams((prev) => ({ ...prev, kernel_size: Number(e.target.value) }))} />
          </div>
        );
      case "arithmetic":
        return (
          <div className="param-group">
            <input type="file" className="param-input" onChange={handleSecondImageChange} />
            <select className="param-input" defaultValue="subtract" onChange={(e) => setParams({ arithmetic_op: e.target.value })}>
              <option value="subtract">Çıkarma</option>
              <option value="multiply">Çarpma</option>
            </select>
          </div>
        );
      default:
        return null;
    }
  };

  return (
    <div className="container">
      <h2>Görüntü İşleme Uygulaması</h2>
      <input type="file" accept="image/*" onChange={handleImageChange} className="file-input" />
      <select className="dropdown" value={operation} onChange={(e) => {
        setOperation(e.target.value);
        setParams({});
        setSecondImage(null);
        setPreviewSecond("");
        setResultUrl("");
      }}>
        <option value="gray">Gri Dönüşüm</option>
        <option value="binary">Binary</option>
        <option value="rotate">Döndürme</option>
        <option value="crop">Kırpma</option>
        <option value="zoom">Yaklaştırma</option>
        <option value="color">Renk Uzamı</option>
        <option value="histogram">Histogram</option>
        <option value="contrast">Kontrast Azalt</option>
        <option value="median">Median</option>
        <option value="double_threshold">Çift Eşik</option>
        <option value="edge">Kenar Bulma</option>
        <option value="noise">Gürültü Ekle</option>
        <option value="denoise">Gürültü Temizle</option>
        <option value="motion">Motion Blur</option>
        <option value="morphology">Morfoloji</option>
        <option value="arithmetic">Aritmetik İşlem</option>
      </select>

      {renderParams()}
      <button onClick={handleSubmit} className="action-button">Uygula</button>

      {operation === "arithmetic" && (previewUrl || previewSecond || resultUrl) && (
        <div className="image-gallery">
          {previewUrl && (
            <div className="image-block">
              <h4>1. Görsel</h4>
              <img src={previewUrl} alt="1. Görsel" className="preview-image" />
            </div>
          )}
          {previewSecond && (
            <div className="image-block">
              <h4>2. Görsel</h4>
              <img src={previewSecond} alt="2. Görsel" className="preview-image" />
            </div>
          )}
          {resultUrl && (
            <div className="image-block">
              <h4>Sonuç</h4>
              <img src={resultUrl} alt="Sonuç" className="preview-image result" onError={(e) => e.target.style.display = 'none'} />
              <a href={resultUrl} download><button className="download-button">İndir</button></a>
            </div>
          )}
        </div>
      )}

      {operation !== "arithmetic" && (previewUrl || resultUrl) && (
        <div className="image-gallery">
          {previewUrl && (
            <div className="image-block">
              <h4>Yüklenen Görsel</h4>
              <img src={previewUrl} alt="Yüklenen" className="preview-image" />
            </div>
          )}
          {resultUrl && (
            <div className="image-block">
              <h4>İşlem Sonucu</h4>
              <img src={resultUrl} alt="Sonuç" className="preview-image result" onError={(e) => e.target.style.display = 'none'} />
              <a href={resultUrl} download><button className="download-button">İndir</button></a>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

export default App;
